script:
var COUNT = {{count}};
var SPEED = {{speed}};

var COLORS = ['#2f6fd0', '#1f9d63', '#d97706', '#7c3aed', '#0891b2', '#be185d', '#4d7c0f', '#b45309', '#0f766e'];

// 固定的一串数字（不用随机：演示要可复现，同一个知识点每次看起来一样）
var BASE = [7, 2, 9, 4, 6, 1, 8, 3, 5];
var values = BASE.slice(0, COUNT);

var COL_W = 420 / COUNT;
var BAR_MAX = 150;
var BASE_Y = 180;

var columns = document.getElementById('columns');
var axis = document.getElementById('axis');
var caption = document.getElementById('caption');
var swapLabel = document.getElementById('swaps');
var compareLabel = document.getElementById('compare');

var bars = [];
var swaps = 0;
var compares = 0;

for (var i = 0; i < COUNT; i += 1) {
  var x = i * COL_W + COL_W * 0.14;
  var w = COL_W * 0.72;
  var h = (values[i] / 9) * BAR_MAX;
  var rect = Sandbox.svgEl('rect');
  rect.setAttribute('x', String(x));
  rect.setAttribute('y', String(BASE_Y - h));
  rect.setAttribute('width', String(w));
  rect.setAttribute('height', String(h));
  rect.setAttribute('rx', '4');
  var color = COLORS[i % COLORS.length];
  rect.setAttribute('fill', color);
  columns.appendChild(rect);

  var label = Sandbox.svgEl('text');
  label.setAttribute('x', String(x + w / 2));
  label.setAttribute('y', String(BASE_Y + 14));
  label.setAttribute('text-anchor', 'middle');
  label.setAttribute('class', 'axis-label');
  label.textContent = String(values[i]);
  axis.appendChild(label);

  // ★ 一根柱子 = 一个固定位置上的槽位：它自己的 rect / 颜色 / 数字标签都不换，
  //   交换时只换「值」（见下面的 complete）。这样步里抓到的元素引用永远有效。
  bars.push({ rect: rect, label: label, value: values[i], color: color, x: x, width: w });
}

// 冒泡排序的每一轮「比较」都变成一个动画步骤：模型不需要懂排序，模板自己跑完
var rounds = [];
var work = values.slice();
for (var pass = 0; pass < work.length - 1; pass += 1) {
  for (var j = 0; j < work.length - 1 - pass; j += 1) {
    var pair = [j, j + 1];
    if (work[j] > work[j + 1]) {
      var tmp = work[j];
      work[j] = work[j + 1];
      work[j + 1] = tmp;
      rounds.push({ pair: pair, swap: true });
    } else {
      rounds.push({ pair: pair, swap: false });
    }
  }
}

function placeBars() {
  for (var i = 0; i < bars.length; i += 1) {
    var h = (bars[i].value / 9) * BAR_MAX;
    bars[i].rect.setAttribute('y', String(BASE_Y - h));
    bars[i].rect.setAttribute('height', String(h));
    bars[i].rect.setAttribute('x', String(i * COL_W + COL_W * 0.14));
    // 颜色与数字都跟着「值」走 —— 换值之后这一格显示的就是换过来的那根柱子。
    bars[i].rect.setAttribute('fill', bars[i].color);
    bars[i].label.textContent = String(bars[i].value);
  }
}

function highlight(bar, color) {
  anime({
    targets: bar.rect,
    stroke: color,
    strokeWidth: 3,
    duration: 120 * SPEED
  });
}

Sandbox.play(function () {
  swaps = 0;
  compares = 0;
  swapLabel.textContent = '交换 0 次';
  compareLabel.textContent = '比较 0 次';
  placeBars();

  var steps = [];
  for (var index = 0; index < rounds.length; index += 1) {
    var round = rounds[index];
    steps.push({
      targets: [bars[round.pair[0]].rect, bars[round.pair[1]].rect],
      stroke: round.swap ? '#d97706' : '#2f6fd0',
      strokeWidth: 3,
      duration: 180 * SPEED,
      begin: (function (r) {
        return function () {
          compares += 1;
          compareLabel.textContent = '比较 ' + compares + ' 次';
          caption.textContent = '比一比第 ' + (r.pair[0] + 1) + ' 根和第 ' + (r.pair[1] + 1) + ' 根：' + (r.swap ? '左边更大，交换' : '顺序正确，不动');
        };
      })(round)
    });
    if (round.swap) {
      steps.push({
        targets: [bars[round.pair[0]].rect, bars[round.pair[1]].rect],
        // ★ 每根柱子走自己的方向（函数值 = 逐目标取值）：原来两根共用 [0, COL_W]，
        //   右边那根会跟着右移一整格 —— 最右一对交换时它整根跑出 viewBox（实测被裁 60 单位）。
        translateX: function (el, i) { return [0, i === 0 ? COL_W : -COL_W]; },
        duration: 260 * SPEED,
        complete: (function (r) {
          return function () {
            // ★ 交换「值」而不是两个 rect 元素：元素与位置是绑死的（见上面的说明），
            //   颜色跟着值走，所以观感与「柱子换了位置」完全一致。
            var a = bars[r.pair[0]];
            var b = bars[r.pair[1]];
            var value = a.value;
            a.value = b.value;
            b.value = value;
            var color = a.color;
            a.color = b.color;
            b.color = color;
            swaps += 1;
            swapLabel.textContent = '交换 ' + swaps + ' 次';
            for (var k = 0; k < bars.length; k += 1) {
              // ★ 必须清 **style.transform**：动画写的是它，而 CSS 优先级高于表现属性，
              //   原来那句 setAttribute('transform', …) 根本盖不住它 —— 残留的位移会一直
              //   叠在 placeBars() 的 x 上，柱子越换越往右跑、最后整根出画。
              bars[k].rect.style.transform = '';
            }
            placeBars();
          };
        })(round)
      });
    }
  }

  steps.push({
    targets: '#columns rect',
    stroke: '#1f9d63',
    strokeWidth: 3,
    duration: 320,
    begin: function () {
      caption.textContent = '排好了：' + work.join('、') + '（一共比较 ' + compares + ' 次、交换 ' + swaps + ' 次）';
    },
    complete: function () {
      Sandbox.progress(1);
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutQuad' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var total = 0;
  if (timeline.duration) total = timeline.duration;
  return {
    pause: function () {
      timeline.pause();
    },
    play: function () {
      timeline.play();
    },
    restart: function () {
      timeline.restart();
    },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > (total || 8000) + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / (total || 8000)));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'sorting-bars', bars: COUNT });
